use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. The host enforces the
/// allowlist with a trap; mirroring it here means one mis-entered subscription
/// is recorded as a failure instead of aborting the whole tick.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the host of an http(s) URL, conservatively. Returns `None` for
/// anything ambiguous, so that it is never sent to the host.
fn host_of(url: &str) -> Option<String> {
    if url
        .chars()
        .any(|c| c.is_whitespace() || c.is_control() || c == '\\')
    {
        return None;
    }
    let lower = url.to_ascii_lowercase();
    let rest_start = if lower.starts_with("https://") {
        8
    } else if lower.starts_with("http://") {
        7
    } else {
        return None;
    };
    let rest = &url[rest_start..];
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() || authority.contains('@') || authority.contains('[') {
        return None;
    }
    let host = match authority.split_once(':') {
        Some((h, port)) => {
            if port.is_empty() || !port.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            h
        }
        None => authority,
    };
    let host = host.strip_suffix('.').unwrap_or(host).to_ascii_lowercase();
    if host.is_empty() {
        return None;
    }
    Some(host)
}

fn allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "url is not an http(s) URL on a permitted host".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
